use crate::common;
use rust_xlsxwriter::{
    ConditionalFormatDataBar, ConditionalFormatIconSet, ConditionalFormatIconType, Workbook,
    XlsxError,
};

// Test an Excel 2010 extension icon set and data bar on the same range.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, row + 1)?;
    }

    // The ThreeTriangles icon set is only available in Excel 2010 and later.
    let conditional_format =
        ConditionalFormatIconSet::new().set_icon_type(ConditionalFormatIconType::ThreeTriangles);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    let conditional_format = ConditionalFormatDataBar::new()
        .set_solid_fill(true)
        .set_border_off(true);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_cond_format31() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format31")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
